import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.CDA9RsCr.js";const g=JSON.parse('{"title":"功能特性","description":"","frontmatter":{},"headers":[],"relativePath":"intro/features.md","filePath":"intro/features.md","lastUpdated":1794581028000}'),l={name:"intro/features.md"};function i(n,a,s,d,h,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><h2 id="实时弹幕抽奖" tabindex="-1">实时弹幕抽奖 <a class="header-anchor" href="#实时弹幕抽奖" aria-label="Permalink to &quot;实时弹幕抽奖&quot;">​</a></h2><p>连接直播间后，应用会持续监听弹幕。观众发送的弹幕只要包含你设定的口令，就会被自动加入抽奖池——不需要主播或房管手动记名单。同一位观众在同一直播间多次发言只会被计入一次，保证机会均等。</p><p>口令留空即「全弹幕收集」：所有发言观众都入池，选人页会明确标出当前模式。开奖时从池中随机抽取指定数量的中奖者，结果同时写入当前配置的历史记录。</p><h2 id="边看边抽" tabindex="-1">边看边抽 <a class="header-anchor" href="#边看边抽" aria-label="Permalink to &quot;边看边抽&quot;">​</a></h2><p>选人页把直播画面、频道列表和弹幕流放在同一屏：</p><ul><li><strong>直播画面</strong>：内嵌 HLS 播放器，跟随当前选中的频道；未开播时显示封面。</li><li><strong>频道列表</strong>：列出已加入的频道，显示主播、在线人数与开播状态，点一下即可切换预览。</li><li><strong>实时弹幕</strong>：显示当前频道的弹幕流，支持 B 站内置表情（含 <code>[oh]</code> 这类口令表情）。</li></ul><p>弹幕区默认贴底跟随新消息；手动向上滚动后停止自动定位，静置约 3 秒后自动恢复贴底。新弹幕会批量合批刷新，避免刷屏时逐条重渲染。</p><h2 id="频繁直播的稳定性" tabindex="-1">频繁直播的稳定性 <a class="header-anchor" href="#频繁直播的稳定性" aria-label="Permalink to &quot;频繁直播的稳定性&quot;">​</a></h2><ul><li><strong>播放器看门狗</strong>：部分直播流会静默卡住（没有 <code>error</code> / <code>stalled</code> 事件，<code>currentTime</code> 不再前进）。播放器每秒检查播放时钟，连续 5 秒无进展时先尝试软恢复，仍失败则重建播放器并换新的播放地址，退避上限 20 秒。</li><li><strong>弹幕断线重连</strong>：弹幕 WebSocket 断开后按退避重连，握手时携带登录态与 <code>buvid3</code>，避免昵称被打码、UID 归零导致所有观众合并成同一人。</li></ul><h2 id="两种登录方式" tabindex="-1">两种登录方式 <a class="header-anchor" href="#两种登录方式" aria-label="Permalink to &quot;两种登录方式&quot;">​</a></h2><ul><li><strong>凭证登录</strong>：从浏览器复制 B 站 Cookie，粘贴后即可登录。</li><li><strong>扫码登录</strong>：点击「扫码登录」生成二维码，用 B 站手机客户端扫描即可，无需手动复制 Cookie。二维码有过期与已扫描状态提示，可随时重新获取。</li></ul><h2 id="多套抽奖配置" tabindex="-1">多套抽奖配置 <a class="header-anchor" href="#多套抽奖配置" aria-label="Permalink to &quot;多套抽奖配置&quot;">​</a></h2><p>为不同场景各存一套配置（Profile），每套独立保存口令、中奖人数、加入的频道和背景图。切换配置时这些设置一起切换，互不干扰，自动保留。</p><h2 id="抽奖历史与导出" tabindex="-1">抽奖历史与导出 <a class="header-anchor" href="#抽奖历史与导出" aria-label="Permalink to &quot;抽奖历史与导出&quot;">​</a></h2><p>每次开奖都会自动记录一条历史，绑定在当前配置下——包含口令、中奖人数、开奖时间和完整中奖名单。设置页的「历史」页签可以：</p><ul><li><strong>单条导出</strong>：把该次中奖名单导出为 Markdown 文件，文件名为 <code>口令-人数-时间.md</code>，内容为「昵称 + UID」的表格。</li><li><strong>单条删除</strong>：删除不需要的历史记录。</li><li><strong>全部删除</strong>：清空当前配置下的全部历史（有确认弹窗）。</li></ul><p>切换配置时历史列表自动切换；删除某套配置时，其历史一并清除。每个配置最多保留最近 100 条。</p><h2 id="界面与主题" tabindex="-1">界面与主题 <a class="header-anchor" href="#界面与主题" aria-label="Permalink to &quot;界面与主题&quot;">​</a></h2><ul><li><strong>深浅色</strong>：可手动切换，首次启动跟随系统偏好，选择自动记住。</li><li><strong>背景</strong>：可选「默认」渐变、春节或假日背景图；也可上传自己的图片作为背景。</li><li><strong>主色调</strong>：从当前背景图采样提取主色，自动生成整套 primary 色阶，四个页面跟着同一套颜色走。</li><li><strong>语言</strong>：内置中文 / English 切换，默认中文。</li></ul><h2 id="交互细节" tabindex="-1">交互细节 <a class="header-anchor" href="#交互细节" aria-label="Permalink to &quot;交互细节&quot;">​</a></h2><ul><li>出结果时直播画面保持比例，中选名单只占剩余高度并在卡片内滚动，页面整体不会被撑出滚动条。</li><li>面板与列表的滚动条只在滚动时显现，静置后自动淡出。</li><li>复制中奖名单优先走浏览器剪贴板，失败时回退到后端原生剪贴板，最后回退到开发桥接的系统命令。</li><li>添加频道支持填房间号，也能直接粘贴直播间链接自动解析。</li></ul>',22)])])}const p=e(l,[["render",i]]);export{g as __pageData,p as default};
